const items=[];const count=document.querySelector('.bag b'),list=document.querySelector('#order-list'),dialog=document.querySelector('dialog');document.querySelectorAll('[data-item]').forEach(b=>b.addEventListener('click',()=>{items.push(b.dataset.item);count.textContent=items.length;b.textContent='✓';setTimeout(()=>b.textContent='+',700)}));document.querySelector('#bag').addEventListener('click',()=>{list.textContent=items.length?items.join(' · '):'Пока пусто';dialog.showModal()});document.querySelector('.x').addEventListener('click',()=>dialog.close());document.querySelector('.order').addEventListener('click',()=>{list.textContent=items.length?'Готово! Это демо-заказ.':'Сначала добавьте напиток';if(items.length){items.length=0;count.textContent=0}});document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(e.currentTarget.reportValidity()){e.currentTarget.querySelector('small').textContent='Готово — демонстрационная подписка оформлена.';e.currentTarget.reset()}});
